param()
$ErrorActionPreference='Continue'
$ProgressPreference='SilentlyContinue'
$AgentVersion='1.1.12'
$Base=Join-Path $env:LOCALAPPDATA 'HomeDesignAutomationV7'
$Root=Join-Path $Base 'LocalAgent'
$GovRoot=Join-Path $Base 'ChromeGovernor'
$StateFile=Join-Path $Root 'state.json'
$ReadbackFile=Join-Path $Root 'VIDEO_LOCAL_RUNTIME_READBACK.json'
$VideoJobStateFile=Join-Path $Root 'video-job-state.json'
$VideoJobLog=Join-Path $Root 'video-job-console.log'
$BaseAgentFile=Join-Path $Root 'HomeDesignLocalAgent-1.1.7-base.ps1'
$NodeGovernor=Join-Path $GovRoot 'chromeGovernorFast.js'
$PolicyFile=Join-Path $GovRoot 'policy.json'
$ReleaseFile=Join-Path $GovRoot 'release.json'
$ReportFile=Join-Path $GovRoot 'state.json'
$InventoryFile=Join-Path $GovRoot 'inventory.json'
$BaseAgentUrl='https://raw.githubusercontent.com/8friend8ship-cloud/notebooklm-webapp-bridge/main/local-agent/releases/1.1.7/HomeDesignLocalAgent.ps1'
$NodeGovernorUrl='https://raw.githubusercontent.com/8friend8ship-cloud/notebooklm-webapp-bridge/main/local-agent/governor/chromeGovernorFast.js'
$PolicyUrl='https://raw.githubusercontent.com/8friend8ship-cloud/notebooklm-webapp-bridge/main/local-agent/governor/policy.json'
$ReleaseUrl='https://raw.githubusercontent.com/8friend8ship-cloud/notebooklm-webapp-bridge/main/runtime/stable/release.json'
$VideoJobUrl='https://raw.githubusercontent.com/8friend8ship-cloud/notebooklm-webapp-bridge/main/local-agent/jobs/video-production.json'
$NormalRoot=Join-Path $env:LOCALAPPDATA 'Google\Chrome\User Data'
$DedicatedUserData=Join-Path $Base 'ChromeUserData'
$DedicatedExtensionRoot=Join-Path $Base 'Extension\NotebookLM-WebApp-Bridge'
New-Item -ItemType Directory -Force -Path $Root,$GovRoot|Out-Null
function ReadJson([string]$Path){if(-not(Test-Path -LiteralPath $Path)){return $null};try{return Get-Content -LiteralPath $Path -Raw -Encoding UTF8|ConvertFrom-Json}catch{return $null}}
function Refresh([string]$Url,[string]$Path,[int]$Timeout=60){$Tmp=$Path+'.download';$Sep=if($Url.Contains('?')){'&'}else{'?'};$U=$Url+$Sep+'hdcb='+[DateTimeOffset]::UtcNow.ToUnixTimeMilliseconds();Invoke-WebRequest -UseBasicParsing -Uri $U -OutFile $Tmp -TimeoutSec $Timeout;Move-Item -LiteralPath $Tmp -Destination $Path -Force}
function GitBlobSha1([string]$Path){$Bytes=[IO.File]::ReadAllBytes($Path);$Header=[Text.Encoding]::ASCII.GetBytes(('blob '+$Bytes.Length+[char]0));$All=New-Object byte[] ($Header.Length+$Bytes.Length);[Buffer]::BlockCopy($Header,0,$All,0,$Header.Length);[Buffer]::BlockCopy($Bytes,0,$All,$Header.Length,$Bytes.Length);$Sha=[Security.Cryptography.SHA1]::Create();try{return (($Sha.ComputeHash($All)|ForEach-Object{$_.ToString('x2')})-join '')}finally{$Sha.Dispose()}}
function QuoteArgs([object[]]$Items){return (($Items|ForEach-Object{$S=[string]$_;if($S -match '[\s"]'){'"'+($S -replace '"','\"')+'"'}else{$S}})-join ' ')}
function KillTree([int]$Pid){try{& taskkill.exe /PID $Pid /T /F 2>$null|Out-Null}catch{try{Stop-Process -Id $Pid -Force -ErrorAction SilentlyContinue}catch{}}}
function RunProcess([string]$File,[string[]]$Args,[int]$Timeout,[string]$Cwd,[string]$LogPath){$Psi=New-Object Diagnostics.ProcessStartInfo;$Psi.FileName=$File;$Psi.WorkingDirectory=$Cwd;$Psi.UseShellExecute=$false;$Psi.CreateNoWindow=$true;$Psi.RedirectStandardOutput=$true;$Psi.RedirectStandardError=$true;$Psi.Arguments=QuoteArgs $Args;$P=New-Object Diagnostics.Process;$P.StartInfo=$Psi;[void]$P.Start();$OT=$P.StandardOutput.ReadToEndAsync();$ET=$P.StandardError.ReadToEndAsync();if(-not $P.WaitForExit($Timeout*1000)){KillTree ([int]$P.Id);try{[void]$P.WaitForExit(3000)}catch{};$O='';$E='';try{$O=$OT.Result}catch{};try{$E=$ET.Result}catch{};($O+"`r`n"+$E)|Set-Content -LiteralPath $LogPath -Encoding UTF8;return [ordered]@{ok=$false;exitCode=124;timedOut=$true;stdout=$O;stderr=$E}};$P.WaitForExit();$O=$OT.Result;$E=$ET.Result;($O+"`r`n"+$E)|Set-Content -LiteralPath $LogPath -Encoding UTF8;return [ordered]@{ok=($P.ExitCode -eq 0);exitCode=$P.ExitCode;timedOut=$false;stdout=$O;stderr=$E}}
function Proc([string]$Needle){try{return @(Get-CimInstance Win32_Process -Filter "Name='powershell.exe'" -ErrorAction SilentlyContinue|Where-Object{$_.CommandLine -and $_.CommandLine -like "*$Needle*"})}catch{return @()}}
function StopLegacyGovernor(){foreach($N in @('ChromeExtensionGovernor.ps1','GovernorDriveSync.ps1')){foreach($P in @(Proc $N)){KillTree ([int]$P.ProcessId)}}}
function TestHost(){try{return Invoke-RestMethod -Uri 'http://127.0.0.1:8765/health' -Method Get -TimeoutSec 3}catch{return $null}}
function FindCentral(){$Target=[Text.Encoding]::UTF8.GetString([Convert]::FromBase64String('MDDspJHsl5DsnojspITtirjsnIQ='));foreach($D in @(Get-PSDrive -PSProvider FileSystem -ErrorAction SilentlyContinue)){$R=[string]$D.Root;if(-not $R){continue};foreach($C in @((Join-Path $R $Target),(Join-Path $R ('My Drive\'+$Target)),(Join-Path $R ('Google Drive\'+$Target)))){if(Test-Path -LiteralPath $C){return $C}}};foreach($C in @((Join-Path $env:USERPROFILE ('My Drive\'+$Target)),(Join-Path $env:USERPROFILE ('Google Drive\'+$Target)))){if(Test-Path -LiteralPath $C){return $C}};return ''}
function RunGovernor(){try{Refresh $NodeGovernorUrl $NodeGovernor 60;Refresh $PolicyUrl $PolicyFile 60;Refresh $ReleaseUrl $ReleaseFile 60;$Node=Get-Command node.exe -ErrorAction SilentlyContinue;if(-not $Node){$Node=Get-Command node -ErrorAction SilentlyContinue};if(-not $Node){return [ordered]@{ok=$false;exitCode=127;timedOut=$false;stderr='NODE_NOT_FOUND'}};$Args=@($NodeGovernor,'--normalRoot',$NormalRoot,'--dedicatedUserData',$DedicatedUserData,'--dedicatedExtensionRoot',$DedicatedExtensionRoot,'--policy',$PolicyFile,'--release',$ReleaseFile,'--agentState',$StateFile,'--report',$ReportFile,'--inventory',$InventoryFile);return RunProcess $Node.Source $Args 60 $GovRoot (Join-Path $GovRoot 'node-governor.log')}catch{return [ordered]@{ok=$false;exitCode=1;timedOut=$false;stderr=$_.Exception.Message}}}
function RunVideoJob([string]$Central){$Meta=Join-Path $Root 'video-production-job.json';try{Refresh $VideoJobUrl $Meta 45}catch{return [ordered]@{status='JOB_META_FETCH_FAILED';ok=$false;error=$_.Exception.Message}};$Job=ReadJson $Meta;if(-not $Job -or -not $Job.enabled){return [ordered]@{status='DISABLED';ok=$true}};$Old=ReadJson $VideoJobStateFile;$Reset=($null -eq $Old -or [string]$Old.jobId -ne [string]$Job.jobId -or [string]$Old.scriptBlobSha1 -ne [string]$Job.scriptBlobSha1);$Attempts=0;if(-not $Reset -and $Old.attempts){$Attempts=[int]$Old.attempts};if(-not $Reset -and [string]$Old.status -eq 'PASS'){return [ordered]@{status='PASS';ok=$true;attempts=$Attempts;jobId=[string]$Job.jobId;scriptBlobSha1=[string]$Job.scriptBlobSha1;skipped='already_passed'}};$Max=[Math]::Max(1,[int]$Job.maxAttempts);if($Attempts -ge $Max){return [ordered]@{status='MAX_ATTEMPTS_REACHED';ok=$false;attempts=$Attempts;jobId=[string]$Job.jobId;scriptBlobSha1=[string]$Job.scriptBlobSha1}};$Script=Join-Path $Root 'Run-VideoProductionAutoJob.ps1';$Raw='https://raw.githubusercontent.com/'+[string]$Job.scriptRepo+'/'+[string]$Job.scriptRef+'/'+[string]$Job.scriptPath;try{Refresh $Raw $Script 60;$Actual=(GitBlobSha1 $Script).ToLowerInvariant();$Expected=([string]$Job.scriptBlobSha1).ToLowerInvariant();if($Actual -ne $Expected){throw ('VIDEO_JOB_HASH_MISMATCH expected='+$Expected+' actual='+$Actual)};$Attempts++;$Timeout=[Math]::Max(60,[Math]::Min(1800,[int]$Job.timeoutSeconds));$Run=RunProcess 'powershell.exe' @('-NoProfile','-ExecutionPolicy','Bypass','-File',$Script) $Timeout $Root $VideoJobLog;$Status=$(if($Run.ok){'PASS'}elseif($Run.timedOut){'TIMEOUT'}else{'ERROR'});$State=[ordered]@{jobId=[string]$Job.jobId;scriptBlobSha1=$Expected;attempts=$Attempts;status=$Status;exitCode=$Run.exitCode;timedOut=[bool]$Run.timedOut;completedAt=(Get-Date).ToString('o');successReadback=[string]$Job.successReadback;error=$(if($Run.ok){''}else{[string]$Run.stderr})};$State|ConvertTo-Json -Depth 20|Set-Content -LiteralPath $VideoJobStateFile -Encoding UTF8;if($Central){$Dir=Join-Path $Central 'Runtime_Readback';New-Item -ItemType Directory -Force -Path $Dir|Out-Null;$State|ConvertTo-Json -Depth 20|Set-Content -LiteralPath (Join-Path $Dir 'VIDEO_AUTO_JOB_STATE.json') -Encoding UTF8;if(Test-Path -LiteralPath $VideoJobLog){Copy-Item -LiteralPath $VideoJobLog -Destination (Join-Path $Dir 'VIDEO_AUTO_JOB_CONSOLE.log') -Force}};return $State}catch{$Attempts++;$State=[ordered]@{jobId=[string]$Job.jobId;scriptBlobSha1=[string]$Job.scriptBlobSha1;attempts=$Attempts;status='ERROR';exitCode=1;timedOut=$false;completedAt=(Get-Date).ToString('o');successReadback=[string]$Job.successReadback;error=$_.Exception.Message};$State|ConvertTo-Json -Depth 20|Set-Content -LiteralPath $VideoJobStateFile -Encoding UTF8;if($Central){$Dir=Join-Path $Central 'Runtime_Readback';New-Item -ItemType Directory -Force -Path $Dir|Out-Null;$State|ConvertTo-Json -Depth 20|Set-Content -LiteralPath (Join-Path $Dir 'VIDEO_AUTO_JOB_STATE.json') -Encoding UTF8};return $State}}
$BaseState=$null;$BaseRun=[ordered]@{ok=$false;exitCode=1;timedOut=$false;stderr='NOT_RUN'}
try{Refresh $BaseAgentUrl $BaseAgentFile 60;$BaseRun=RunProcess 'powershell.exe' @('-NoProfile','-ExecutionPolicy','Bypass','-File',$BaseAgentFile) 60 $Root (Join-Path $Root 'base-self-heal.log');StopLegacyGovernor;$BaseState=ReadJson $StateFile}catch{$BaseState=ReadJson $StateFile}
$Host=TestHost
$Central=FindCentral
$Gov=RunGovernor
$DriveOk=$false
if($Central -and $Gov.ok -and (Test-Path -LiteralPath $ReportFile) -and (Test-Path -LiteralPath $InventoryFile)){try{$Dir=Join-Path $Central 'Chrome_Extension_Governor';New-Item -ItemType Directory -Force -Path $Dir|Out-Null;Copy-Item -LiteralPath $ReportFile -Destination (Join-Path $Dir 'CHROME_EXTENSION_GOVERNOR_RESULT.json') -Force;Copy-Item -LiteralPath $InventoryFile -Destination (Join-Path $Dir 'CHROME_EXTENSION_INVENTORY.json') -Force;$DriveOk=$true}catch{}}
$Video=RunVideoJob $Central
$S=@{}
if($BaseState){foreach($P in $BaseState.PSObject.Properties){$S[$P.Name]=$P.Value}}
$S.agentVersion=$AgentVersion;$S.hostHealthy=$(if($Host){[bool]$Host.ok}else{$false});$S.commandHostVersion=$(if($Host){[string]$Host.version}else{''});$S.commandHostAsyncJobs=$(if($Host){[bool]$Host.asyncJobs}else{$false});$S.baseSelfHealOk=[bool]$BaseRun.ok;$S.governorMode='AGENT_5MIN_NODE_DIRECT';$S.governorCycleOk=[bool]$Gov.ok;$S.governorExitCode=$Gov.exitCode;$S.governorError=[string]$Gov.stderr;$S.governorDriveSyncOk=$DriveOk;$S.governorCentralPath=$Central;$S.videoAutoJobStatus=[string]$Video.status;$S.videoAutoJobAttempts=$(if($Video.attempts){[int]$Video.attempts}else{0});$S.videoAutoJobId=$(if($Video.jobId){[string]$Video.jobId}else{''});$S.updatedAt=(Get-Date).ToString('o')
$S|ConvertTo-Json -Depth 30|Set-Content -LiteralPath $StateFile -Encoding UTF8;$S|ConvertTo-Json -Depth 30|Set-Content -LiteralPath $ReadbackFile -Encoding UTF8
if($Central){$Dir=Join-Path $Central 'Runtime_Readback';New-Item -ItemType Directory -Force -Path $Dir|Out-Null;$S|ConvertTo-Json -Depth 30|Set-Content -LiteralPath (Join-Path $Dir 'VIDEO_LOCAL_RUNTIME_READBACK.json') -Encoding UTF8}
if(-not $Host -or -not $Host.ok){exit 10}
if(-not $Gov.ok){exit 11}
if([string]$Video.status -in @('ERROR','TIMEOUT','MAX_ATTEMPTS_REACHED','JOB_META_FETCH_FAILED')){exit 12}
exit 0
